PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, tenant_id TEXT, email TEXT NOT NULL UNIQUE, name TEXT, role TEXT NOT NULL DEFAULT 'VIEWER', created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tenant_id TEXT, kind TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS entitlements (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, capability_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', granted_at TEXT NOT NULL, expires_at TEXT, UNIQUE(tenant_id, capability_id), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, type TEXT NOT NULL, name TEXT NOT NULL, owner TEXT, state TEXT NOT NULL DEFAULT 'DISCOVERED', risk_level TEXT NOT NULL DEFAULT 'LOW', metadata_json TEXT DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS asset_relationships (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, from_id TEXT NOT NULL, to_id TEXT NOT NULL, relationship TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, asset_id TEXT, type TEXT NOT NULL, severity TEXT NOT NULL, context_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', definition_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS policy_versions (id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version INTEGER NOT NULL, definition_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(policy_id) REFERENCES policies(id));
CREATE TABLE IF NOT EXISTS decisions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, event_id TEXT, decision TEXT NOT NULL, action TEXT NOT NULL, risk_score INTEGER NOT NULL, risk_level TEXT NOT NULL, reasons_json TEXT NOT NULL, engine_version TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS actions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, decision_id TEXT NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL, result_json TEXT DEFAULT '{}', created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, event_id TEXT, decision_id TEXT, action_id TEXT, type TEXT NOT NULL, payload_json TEXT NOT NULL, integrity_hash TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS findings (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, asset_id TEXT, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', owner TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS remediation_tasks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, finding_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', owner TEXT, due_at TEXT, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS retests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, finding_id TEXT NOT NULL, result TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS investigations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, event_id TEXT, title TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'DETECTED', summary TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS investigation_events (id TEXT PRIMARY KEY, investigation_id TEXT NOT NULL, event_id TEXT NOT NULL, sequence INTEGER NOT NULL, FOREIGN KEY(investigation_id) REFERENCES investigations(id), FOREIGN KEY(event_id) REFERENCES events(id));
CREATE TABLE IF NOT EXISTS changes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, asset_id TEXT, change_type TEXT NOT NULL, before_json TEXT, after_json TEXT, impact_json TEXT, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS problem_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, problem TEXT NOT NULL, desired_outcome TEXT, urgency TEXT, affected_systems TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS control_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, problem TEXT NOT NULL, urgency TEXT, affected_assets TEXT, requested_outcome TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, scopes_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL, last_used_at TEXT, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_type TEXT NOT NULL, actor_id TEXT, tenant_id TEXT, action TEXT NOT NULL, target_type TEXT, target_id TEXT, metadata_json TEXT DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE INDEX IF NOT EXISTS idx_events_tenant_created ON events(tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_evidence_tenant_created ON evidence(tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_assets_tenant ON assets(tenant_id);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_created ON audit_log(tenant_id, created_at DESC);
